private void showDownloadSnackbar(){
  snackShown=true;
  Snackbar.make(getRootView(),R.string.resized_images_download_full_image,Snackbar.LENGTH_LONG).setCallback(new Snackbar.Callback(){
    @Override public void onDismissed(Snackbar snackbar, int event){
      super.onDismissed(snackbar,event);
      snackShown=false;
    }
  }).setAction(R.string.common_yes, v -> {
    try {
      previewImageFragment.downloadFile();
    } catch (Exception e) {
      // Handle the exception, e.g., log it or show an error message
      e.printStackTrace();
    }
  }).show();
}
